+// Scalar and whole-span accesses share page proofs without sharing read/write
+// permissions. Exercise straight paths, conditional joins and moving loop bases.
+static bool test_span_page_reuse() {
+#ifdef __EMSCRIPTEN__
+    struct restore { bool folded=r12l1::dyncom_folded_tlb; unsigned mode=eka2l1::common::code_tracking::unsafe_code_mode;
+        ~restore(){r12l1::dyncom_folded_tlb=folded;eka2l1::common::code_tracking::unsafe_code_mode=mode;}
+    } saved;
+    eka2l1::common::code_tracking::unsafe_code_mode=3;
+    const std::vector<std::vector<unsigned>> programs={
+        {0xe5910000u,0xe891001cu,0xe5850000u,0xe885001cu,0xe5956000u},
+        {0xe8b1001cu,0xe5916000u,0xe2811004u,0xe8a5001cu,0xe25aa001u,0x1afffff9u},
+        {0xe3590000u,0x1891001cu,0x05950000u,0x1a000000u,0xe89501c0u,0xe89101c0u,0xe88501c0u,0xe5d5b000u}
+    };
+    const std::vector<wasm_import_func> imports={{"env","tlb_read32",2,true},{"env","tlb_write32",3,false},
+        {"env","tlb_read8",2,true},{"env","tlb_write8",3,false},{"env","tlb_read16",2,true},{"env","tlb_write16",3,false}};
+    unsigned checks=0;
+    for(bool folded:{false,true})for(bool deferred:{false,true})
+    for(auto policy:{arm_ir_policy::disabled,arm_ir_policy::loop_budget_chunks}) {
+        r12l1::dyncom_folded_tlb=folded;
+        for(unsigned program=0;program<programs.size();++program) {
+            const auto &words=programs[program];const auto *bytes=reinterpret_cast<const std::uint8_t*>(words.data());
+            auto tr=translate_arm_block(bytes,words.size()*4,0x1000,nullptr,nullptr,true,false,true,true,nullptr,deferred,policy);
+            auto module=build_wasm_module({tr.func},imports);
+            for(unsigned permission:{0u,1u,2u,3u})for(unsigned address:{0x8000u,0x8fd8u,0x8ffcu})
+            for(bool alias:{false,true})for(unsigned selector:{0u,1u})
+            for(unsigned budget=0;budget<=(program==1?19u:unsigned(words.size()+1));++budget) {
+                test_mem actual;actual.write_code(0x1000,{bytes,bytes+words.size()*4});
+                for(unsigned a=0x7000;a<0xc000;a+=4)actual.write32(a,(a*37)^0x87654321u);
+                test_mem expected=actual;r12l1::exclusive_monitor monitor(1);auto cpu=make_cpu(expected,monitor);
+                r12l1::tlb tlb(12,folded);for(unsigned a=0x7000;a<0xc000;a+=4096)tlb.add(a,actual.data.data()+a,permission);
+                alignas(8) unsigned state[256]{};
+                for(unsigned r=0;r<16;++r) {
+                    const unsigned value=r==1?address:r==5?(alias?address:0xa000u+(address&4095)):
+                        r==9?selector:r==10?3u:r==15?0x1000u:0x12340000u+r;
+                    state[r]=value;cpu->set_reg(r,value);
+                }
+                state[state_offsets::CPSR/4]=0xa0000010u;state[state_offsets::MODE/4]=16;
+                state[state_offsets::NFLAG/4]=state[state_offsets::CFLAG/4]=1;cpu->set_cpsr(0xa0000010u);
+                state[state_offsets::AOT_BUDGET/4]=budget;state[state_offsets::NIRQ/4]=1;
+                state[state_offsets::AOT_TLB/4]=reinterpret_cast<std::uintptr_t>(tlb.entries);
+                g_test_mem=&actual;
+                const int count=js_run_aot_wasm(module.data(),module.size(),reinterpret_cast<std::uint8_t*>(state),sizeof(state));
+                g_test_mem=nullptr;
+                if(count<0||count>int(budget)){printf(" FAIL span reuse progress\n");return false;}
+                if(count)cpu->run(count);
+                for(unsigned r=0;r<16;++r)if(state[r]!=cpu->get_reg(r)) {
+                    printf(" FAIL span reuse p=%u folded=%d deferred=%d policy=%d permission=%u address=%x alias=%d selector=%u budget=%u count=%d R%u %x vs %x\n",
+                        program,folded,deferred,int(policy),permission,address,alias,selector,budget,count,r,state[r],cpu->get_reg(r));return false;
+                }
+                for(auto flag:{std::pair<unsigned,unsigned>{state_offsets::NFLAG,31},{state_offsets::ZFLAG,30},
+                    {state_offsets::CFLAG,29},{state_offsets::VFLAG,28},{state_offsets::TFLAG,5}})
+                    if(state[flag.first/4]!=((cpu->get_cpsr()>>flag.second)&1)) {printf(" FAIL span reuse flags\n");return false;}
+                if(actual.data!=expected.data){printf(" FAIL span reuse memory\n");return false;}
+                ++checks;
+            }
+        }
+        // A byte access can prime a page even when the later word span is
+        // unaligned or crosses its end. An opposite access cannot grant rights.
+        for(bool warm_write:{false,true})for(bool span_write:{false,true}) {
+            const unsigned words[]={warm_write?0xe5c10000u:0xe5d10000u,span_write?0xe881001cu:0xe891001cu};
+            auto tr=translate_arm_block(reinterpret_cast<const std::uint8_t*>(words),sizeof(words),0x1000,
+                nullptr,nullptr,true,false,true,true,nullptr,false,arm_ir_policy::disabled);
+            auto module=build_wasm_module({tr.func},imports);
+            for(unsigned permission:{1u,2u,3u})for(unsigned address:{0x8000u,0x8001u,0x8ffcu,0u}) {
+                test_mem memory;r12l1::tlb tlb(12,folded);tlb.add(address?0x8000:0x200000,memory.data.data()+0x8000,permission);
+                alignas(8) unsigned state[256]{};state[1]=address;state[15]=0x1000;
+                state[state_offsets::CPSR/4]=16;state[state_offsets::NIRQ/4]=1;state[state_offsets::AOT_BUDGET/4]=2;
+                state[state_offsets::AOT_TLB/4]=reinterpret_cast<std::uintptr_t>(tlb.entries);
+                g_test_mem=&memory;g_all_memory_helper_calls=0;
+                const int count=js_run_aot_wasm(module.data(),module.size(),reinterpret_cast<std::uint8_t*>(state),sizeof(state));
+                g_test_mem=nullptr;
+                const bool fast=(permission&(warm_write?2:1))&&(permission&(span_write?2:1))&&address==0x8000;
+                if(count<1||count>2||(fast?(count!=2||g_all_memory_helper_calls!=0):g_all_memory_helper_calls==0)) {
+                    printf(" FAIL span reuse guard warm=%d write=%d permission=%u address=%x count=%d helpers=%u\n",
+                        warm_write,span_write,permission,address,count,g_all_memory_helper_calls);return false;
+                }
+                ++checks;
+            }
+        }
+    }
+    // The first LDM fills the read-page cache. A callback during a crossing
+    // LDM remaps that page before its remaining words, so reuse must be cleared.
+    for(bool folded:{false,true})for(bool endian:{false,true}) {
+        r12l1::dyncom_folded_tlb=folded;
+        const unsigned words[]={0xe891001cu,0xe89501c0u};
+        auto tr=translate_arm_block(reinterpret_cast<const std::uint8_t*>(words),sizeof(words),0x1000,
