+        memory.write32(0xa000,23);memory.write32(0xa004,29);
+        r12l1::tlb tlb(12,folded);tlb.add(0x9000,memory.data.data()+0x9000,1);
+        alignas(8) unsigned state[256]{};state[1]=0x9000;state[5]=0x8ffc;state[15]=0x1000;
+        state[state_offsets::CPSR/4]=16;state[state_offsets::NIRQ/4]=1;state[state_offsets::AOT_BUDGET/4]=2;
+        state[state_offsets::AOT_TLB/4]=reinterpret_cast<std::uintptr_t>(tlb.entries);
+        bool observed=false;
+        g_read32_observer=[&](unsigned ptr,unsigned address) {
+            if(address!=0x8ffc)return;auto *v=reinterpret_cast<unsigned*>(ptr);
+            observed=v[15]==0x1004&&v[2]==11&&v[3]==13&&v[4]==17;
+            tlb.add(0x9000,memory.data.data()+0xa000,1);
+            if(endian)v[state_offsets::CPSR/4]|=0x200;
+        };
+        g_test_mem=&memory;g_all_memory_helper_calls=0;
+        const int count=js_run_aot_wasm(module.data(),module.size(),reinterpret_cast<std::uint8_t*>(state),sizeof(state));
+        g_test_mem=nullptr;g_read32_observer={};
+        // Raw test helpers deliberately do not emulate byte swapping. Their
+        // invocation on each remaining word is the endian-path assertion.
+        if(count!=2||!observed||state[6]!=7||state[7]!=(endian?11u:23u)||state[8]!=(endian?13u:29u)
+            ||g_all_memory_helper_calls!=(endian?3u:1u)) {
+            printf(" FAIL span reuse callback folded=%d endian=%d count=%d observed=%d values=%u,%u,%u helpers=%u\n",
+                folded,endian,count,observed,state[6],state[7],state[8],g_all_memory_helper_calls);return false;
+        }
+        ++checks;
+    }
+    printf(" PASS span page reuse (%u state/memory/budget, permission, alignment, crossing and callback checks)\n",checks);
 #endif
     return true;
 }
@@ -5490,6 +5608,7 @@
 }

